const rtdal008461Source0001 = "cch <- function(formula, data, subcoh, id, stratum=NULL, cohort.size, \n                method=c(\"Prentice\", \"SelfPrentice\", \"LinYing\",\"I.Borgan\",\"II.Borgan\"),\n                robust=FALSE){\n    call <- match.call()\n    if (missing(data)) data <- parent.frame()\n    if (is.data.frame(data)){\n        if (inherits(id,\"formula\"))\n            id<- stats::model.frame(id,data,na.action=na.fail)[,1]\n        if (inherits(subcoh,\"formula\"))\n            subcoh<- stats::model.frame(subcoh,data,na.action=na.fail)[,1]\n        if (inherits(stratum,\"formula\"))\n            stratum<- stats::model.frame(stratum,data,na.action=na.fail)[,1]\n    }\n\n    ## Check id, subcoh and cohort.size variables\n    if(length(id)!=length(unique(id)))\n        stop(\"Multiple records per id not allowed\")\n    if (is.logical(subcoh))\n        subcoh <- as.numeric(subcoh)\n    tt <- table(subcoh)\n    if(min(charmatch(names(tt), c(\"0\",\"1\"), 0))==0)\n        stop(\"Permissible values for subcohort indicator are 0/1 or TRUE/FALSE\")\n    if(length(id)>sum(cohort.size))\n        stop(\"Number of records greater than cohort size\")\n    nn <- cohort.size\t\n    method<-match.arg(method)\n    stratified<-method %in% c(\"I.Borgan\",\"II.Borgan\")\n    if (!is.null(stratum))\n        stratum<-factor(stratum)\n    if (stratified){\n        if (robust)\n            warning(\"`robust' not implemented for stratified analysis.\")\n        if (is.null(stratum))\n            stop(\"method (\",method,\") requires 'stratum'\")\n        if (length(cohort.size)!=length(levels(stratum)))\n            stop(\"cohort.size and stratum do not match\")\n        if (!(all(levels(stratum) %in% names(cohort.size))))\n            warning(\"stratum levels and names(cohort.size) do not agree\")\n        subcohort.sizes<-table(stratum)\n    } else if(!stratified) {\n        if (!(method ==\"LinYing\") && robust)\n            warning(\"`robust' ignored for  method (\",method,\")\")\n        if (!is.null(stratum))\n            warning(\"'stratum' ignored for method (\",method,\")\")\n        if (length(cohort.size)!=1)\n            stop(\"cohort size must be a scalar for unstratified analysis\")\n        subcohort.sizes<-length(id)\n    }\n    if (any(subcohort.sizes>cohort.size))\n        stop(\"Population smaller than sample in some strata\")\n    ## Evaluate model formula\n    m <- match.call(expand.dots=FALSE)\n    m$method <- m$cohort.size <- m$id <- m$subcoh <- m$stratum <-m$robust<- NULL\n    m[[1L]] <- quote(stats::model.frame)\n    m <- eval(m,sys.parent())\n    Terms <- attr(m,\"terms\")\n    Y <- model.extract(m, \"response\")\n    if(!inherits(Y, \"Surv\"))\n        stop(\"Response must be a survival object\")\n    type <- attr(Y, \"type\")\n    itype<-charmatch(type,c(\"right\",\"counting\"),nomatch=0)\n    cens<-switch(itype+1,\n                 stop(paste(\"Cox model doesn't support \\\"\", type, \"\\\" survival data\", sep = \"\")),\n                 Y[,2],\n                 Y[,3])\n    if (any(!subcoh & !cens))\n        stop(sum(!subcoh & !cens),\"censored observations not in subcohort\")\n    cc<-cens+1-subcoh\n    texit<-switch(itype+1, stop(), Y[,1], Y[,2])\n    tenter<-switch(itype+1, stop(), rep(0,length(texit)), Y[,1])\n    X <- model.matrix(Terms, m)\n    X <- X[,2:ncol(X)]\n    fitter <- get(method)\n\n    # The artificial offset is 1/2 the minimal distance between events\n    # If there is only one unique event time then any offset is ok\n    if (ncol(Y)==3) dtime <- unique(Y[cens==1,2])\n    else dtime <- unique(Y[cens==1, 1])\n    if (length(dtime) > 1) delta <- min(diff(sort(dtime))) /2 \n    else delta <- 1\n\n    if (stratified)        \n        out<-fitter(tenter=tenter, texit=texit, cc=cc, id=id, X=X,\n                    stratum=as.numeric(stratum), stratum.sizes=cohort.size,\n                    delta)\n    else\n        out<-fitter(tenter=tenter, texit=texit, cc=cc, id=id, X=X, ntot=nn, robust=robust, delta)\n    out$method <- method\n    names(out$coefficients) <- dimnames(X)[[2]]\n    if(!is.null(out$var))\n        dimnames(out$var) <- list(dimnames(X)[[2]], dimnames(X)[[2]])\n    if(!is.null(out$naive.var))\n        dimnames(out$naive.var) <- list(dimnames(X)[[2]], dimnames(X)[[2]])\n    out$call <- call\n    out$cohort.size <- cohort.size\n    out$stratified<-stratified\n    if (stratified){\n        out$stratum<-stratum\n        out$subcohort.size <-subcohort.sizes\n    } else {\n        out$subcohort.size <- tt[2]\n    }\n    class(out) <- \"cch\"\n    out\n}"

const rtdal008461Source0002 = `Prentice <- function(tenter, texit, cc,  id, X, ntot,robust, delta){
    cens <- as.numeric(cc>0) # Censorship indicators
    subcoh <- as.numeric(cc<2) # Subcohort indicators

    ## Calculate Prentice estimate
    ent2 <- tenter
    ent2[cc==2] <- texit[cc==2]- delta
    fit1 <- coxph(Surv(ent2,texit,cens)~X, x=TRUE, timefix=FALSE)

    ## Calculate Prentice estimate and variance
    nd <- sum(cens) # Number of failures
    nc <- sum(subcoh) # Number in subcohort
    ncd <- sum(cc==1) #Number of failures in subcohort
    X <- as.matrix(X)
    aent <- c(tenter[cc>0],tenter[cc<2])
    aexit <- c(texit[cc>0],texit[cc<2])
    aX <- rbind(as.matrix(X[cc>0,]),as.matrix(X[cc<2,]))
    aid <- c(id[cc>0],id[cc<2])
    dum <- rep(-100,nd)
    dum <- c(dum,rep(0,nc))
    gp <- rep(1,nd)
    gp <- c(gp,rep(0,nc))
    fit <- coxph(Surv(aent,aexit,gp)~aX+offset(dum), cluster= aid, x=TRUE,
                 iter.max=35,init=fit1$coefficients, timefix=FALSE)
    db <- resid(fit,type="dfbeta")
    db <- as.matrix(db)
    db <- db[gp==0,]
    fit$phase2var<-(1-(nc/ntot))*t(db)%*%(db)
    fit$naive.var <- fit$naive.var+fit$phase2var
    fit$var<-fit$naive.var
    
    fit$coefficients <- fit$coef <- fit1$coefficients
    fit
}`

const rtdal008461Source0007 = `vcov.cch<-function(object,...) object$var`

const rtdal008461Source0008 = `"print.cch"<- function(x,...)
{
    ## produces summary from an x of the class "cch"
    call<-x$call
    coef <- coef(x)
    method <- x$method
    se <- sqrt(diag(vcov(x)))
    Z<- abs(coef/se)
    p<- pnorm(Z)
    cohort.size<-x$cohort.size
    subcohort.size<-x$subcohort.size
    coefficients <- matrix(0, nrow = length(coef), ncol = 4)
    dimnames(coefficients) <- list(names(coef), c("Value", 
                                                  "SE", "Z", "p"))
    coefficients[, 1] <- coef
    coefficients[, 2] <- se
    coefficients[, 3] <- Z
    coefficients[, 4] <- 2*(1-p)

 
    if (x$stratified){
        cat("Exposure-stratified case-cohort analysis,", x$method, "method.\n")
        m<-rbind(subcohort=x$subcohort.size, cohort=x$cohort.size)
        print(m,quote=FALSE)
    } else{
        cat("Case-cohort analysis,")
        cat("x$method,", x$method,"\n with subcohort of",
            x$subcohort.size,"from cohort of", x$cohort.size,"\n\n")
    }
    cat("Call: "); print(x$call)
    cat("\nCoefficients:\n")
    print(coefficients)
    invisible(x)
}`

const rtdal008461Source0009 = `"summary.cch"<-function(object,...)
{
    ## produces summary from an object of the class "cch"
    call<-object$call
	coef <- coef(object)
	method <- object$method
	se <- sqrt(diag(vcov(object)))
      Z<- abs(coef/se)
      p<- pnorm(Z)
      cohort.size<-object$cohort.size
      subcohort.size<-object$subcohort.size
    coefficients <- matrix(0, nrow = length(coef), ncol = 4)
    dimnames(coefficients) <- list(names(coef), c("Value", 
                                                  "SE", "Z", "p"))
    coefficients[, 1] <- coef
    coefficients[, 2] <- se
    coefficients[, 3] <- Z
    coefficients[, 4] <- 2*(1-p)
    structure(list(call=call, method=method, cohort.size=cohort.size,
                   subcohort.size=subcohort.size, coefficients = coefficients,
                   stratified=object$stratified), 
              class = "summary.cch")
}`

const rtdal008461Source0010 = `print.summary.cch <- function(x,digits=3,...){

    if (x$stratified){
        cat("Exposure-stratified case-cohort analysis,", x$method, "method.\n")
        m<-rbind(subcohort=x$subcohort.size, cohort=x$cohort.size)
        print(m,quote=FALSE)
    } else{
        cat("Case-cohort analysis,")
        cat("x$method,", x$method,"\n with subcohort of",
            x$subcohort.size,"from cohort of", x$cohort.size,"\n\n")
    }
    cat("Call: "); print(x$call)
    cat("\nCoefficients:\n")
    output<-cbind(Coef=x$coefficients[,1],HR=exp(x$coefficients[,1]),
                  "(95%"=exp(x$coefficients[,1]-1.96*x$coefficients[,2]),
                  "CI)"=exp(x$coefficients[,1]+1.96*x$coefficients[,2]),
                  "p"=x$coefficients[,4]
                  )
    print(round(output,3))
    invisible(x)
}`

