	// R|         rval <-  list(coefficients  = coef/rescale,
	// R|                       var    = scmat %*% var %*% scmat,
	// R|                       loglik = loglik,
	// R|                       score  = sctest,
	// R|                       iter   = iter,
	// R|                       linear.predictors = lp.unsort,
	// R|                       residuals = resid,
	// R|                       means = means,
	// R|                       method = method,
