const rtdal008497Source0001 = `logLik.coxph <- function(object, ...) {
    out <- object$loglik[2]
    if (!is.null(object$df)) attr(out, "df") <- sum(object$df)
    else  attr(out, 'df') <- sum(!is.na(coefficients(object)))
    attr(out, "nobs") <- object$nevent
    class(out) <- 'logLik'
    out
    }`

const rtdal008497Source0002 = `logLik.coxph.null <- function(object, ...) {
    out <- object$loglik[1]
    attr(out, "df") <- 0
    attr(out, "nobs") <- object$nevent
    class(out) <- "logLik"
    out
}`

const rtdal008497Source0003 = `logLik.survreg <- function(object, ...) {
    out <- object$loglik[2]
    dd <- diag(object$var)
    if (!is.null(object$df)) attr(out, "df") <- sum(object$df)
    else attr(out, 'df') <- sum(!is.na(dd) & dd > 0)
#    attr(out, "nobs") <- sum(object$df) + object$df.residual
    class(out) <- 'logLik'
    out
    }`

