	// R|     # This line should be unreachable, unless they call "surfitAJ" directly
	// R|     if (type !='mright' && type!='mcounting')
	// R|          stop(paste("multi-state computation doesn't support \"", type,
	// R|                           "\" survival data", sep=''))
	// R|
	// R|     # Use survcheck to validate the data
	// R|     if (length(id) ==0) id <- seq_along(X)  # a dummy value for later work
	// R|     if (missing(istate) || is.null(istate))
	// R|         mcheck <- survcheck2(Y, id)
	// R|     else mcheck <- survcheck2(Y, id, istate)
	// R|     if (mcheck$flag["overlap"] > 0)
	// R|         stop("a subject has overlapping time intervals")
	// R|     if (any(mcheck$flag > 0)) stop("one or more flags are >0 in survcheck")
	// R|     # We may eventually remove the line above, then the line below is active
	// R|     if (mcheck$flag["gap"] > 0 || mcheck$flag["jump"] > 0)
	// R|         warning("subject(s) with time gaps, results are questionable")
	// R|
	// R|     istate <- mcheck$istate  # this copy will have the levels set properly
	// R|     states <- mcheck$states
	// R|     nstate <- length(states)
	// R|     if (!identical(states, attr(Y, "states"))) { # new states are a superset
	// R|         smap <- c(0, match(attr(Y, "states"), states))
	// R|         Y[,ncol(Y)] <- smap[Y[,ncol(Y)] +1]
	// R|         attr(Y, 'states') <- states
	// R|     }
	// R|
	// R|     # Now that we know the states, verify that p0 is correct (if present)
	// R|     if (!missing(p0) && length(p0) >0) {
