const rtdal008635Source0008 = `Datedate <- function(x) {
    # Dates have an origin of 1/1/1970, dates of 1/1/1960
    offset <- as.numeric(as.Date("1970-01-01") - as.Date("1960-01-01")) 
    y <- as.numeric(x) + offset
    class(y) <- "date"
    y
}`

